module line_intersection_counter (input clk, input rst_n, input start, input [15:0] x0, y0, x1, y1, input [1:0] segment_index, input load_enable, output reg [7:0] result, output reg done, output reg error); reg signed [15:0] seg0_x0, seg0_y0, seg0_x1, seg0_y1; reg signed [15:0] seg1_x0, seg1_y0, seg1_x1, seg1_y1; reg signed [15:0] seg2_x0, seg2_y0, seg2_x1, seg2_y1; reg signed [15:0] seg3_x0, seg3_y0, seg3_x1, seg3_y1; reg [2:0] state; reg [3:0] expected_segment; reg [5:0] pair_index; reg [7:0] result_reg; reg done_reg; reg error_reg; always @(posedge clk or !rst_n) begin if (!rst_n) begin state <= 3'b000; expected_segment <= 4'b0000; pair_index <= 6'b000000; result_reg <= 8'b00000000; done_reg <= 1'b0; error_reg <= 1'b0; end end always @(posedge clk) begin if (state == 3'b000) begin if (start) begin state <= 3'b001; expected_segment <= 4'b0000; end end else if (state == 3'b001) begin if (load_enable) begin if (segment_index == expected_segment) begin case (expected_segment) 4'b0000: seg0_x0 <= signed(x0); seg0_y0 <= signed(y0); seg0_x1 <= signed(x1); seg0_y1 <= signed(y1); 4'b0001: seg1_x0 <= signed(x0); seg1_y0 <= signed(y0); seg1_x1 <= signed(x1); seg1_y1 <= signed(y1); 4'b0010: seg2_x0 <= signed(x0); seg2_y0 <= signed(y0); seg2_x1 <= signed(x1); seg2_y1 <= signed(y1); 4'b0011: seg3_x0 <= signed(x0); seg3_y0 <= signed(y0); seg3_x1 <= signed(x1); seg3_y1 <= signed(y1); default: ; endcase expected_segment <= expected_segment + 1; if (expected_segment == 4) begin state <= 3'b010; end end end end else if (state == 3'b010) begin state <= 3'b011; done_reg <= 1'b1; result_reg <= 8'b00000000; error_reg <= 1'b0; end end end assign result = result_reg; assign done = done_reg; assign error = error_reg; endmodule